def backfill_marketing_attribution_mode(apps, schema_editor):
    """Run the backfill, except on fresh databases.

    Skipped there (pytest, CI, and the sqlite DB export replay the whole migration
    chain with no prod data to backfill) — running data migrations there has broken
    the DB export before.
    """
    is_ci = os.environ.get("CI", "").lower() in ("1", "true", "yes")
    if "pytest" in sys.modules or is_ci or config("SQLITE_EXPORT_MODE", parser=bool, default="false"):
        return
    copy_enabled_flag_to_mode(apps)


def copy_enabled_flag_to_mode(apps):
    """Carry `enable_marketing_attribution` forward into `marketing_attribution_mode`.

    Updates revisions as well as live rows: the editor loads a page's latest revision, so a
    revision without the new field would show "Disabled" and switch attribution off on the
    next publish. Covering every revision also keeps reverting to an older one safe.
    """
    ContentType = apps.get_model("contenttypes", "ContentType")
    Revision = apps.get_model("wagtailcore", "Revision")

    for model_name in PAGE_MODELS:
        Model = apps.get_model("cms", model_name)
        Model.objects.filter(enable_marketing_attribution=True, marketing_attribution_mode="").update(marketing_attribution_mode="enabled")

        content_type = ContentType.objects.get_for_model(Model)
        revisions = Revision.objects.filter(content_type=content_type, content__enable_marketing_attribution=True)
        for revision in revisions.iterator():
            if not revision.content.get("marketing_attribution_mode"):
                revision.content["marketing_attribution_mode"] = "enabled"
                revision.save(update_fields=["content"])


